fn escape_string(text: &str) -> String {
    let mut escaped = String::with_capacity(text.len());
    for character in text.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\u{08}' => escaped.push_str("\\b"),
            '\u{09}' => escaped.push_str("\\t"),
            '\u{0a}' => escaped.push_str("\\n"),
            '\u{0c}' => escaped.push_str("\\f"),
            '\u{0d}' => escaped.push_str("\\r"),
            character if character <= '\u{1f}' => {
                escaped.push_str(&format!("\\u{:04x}", character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped
}

pub fn canonicalize(value: &Json) -> String {
    match value {
        Json::Null => "null".into(),
        Json::Bool(true) => "true".into(),
        Json::Bool(false) => "false".into(),
        Json::Number(number) => number.to_string(),
        Json::String(text) => format!("\"{}\"", escape_string(text)),
        Json::Array(items) => {
            let inner: Vec<String> = items.iter().map(canonicalize).collect();
            format!("[{}]", inner.join(","))
        }
        Json::Object(entries) => {
            let mut sorted_entries: Vec<&(String, Json)> = entries.iter().collect();
            sorted_entries.sort_by(|(left, _), (right, _)| {
                left.encode_utf16().cmp(right.encode_utf16())
            });

            let inner: Vec<String> = sorted_entries
                .into_iter()
                .map(|(key, nested)| {
                    format!("\"{}\":{}", escape_string(key), canonicalize(nested))
                })
                .collect();
            format!("{{{}}}", inner.join(","))
        }
    }
}

