mod tests {
    use super::{canonicalize, Json};

    #[test]
    fn canonicalizes_nested_values_without_whitespace() {
        let value = Json::Object(vec![
            (
                "z".into(),
                Json::Array(vec![Json::Bool(true), Json::Object(vec![("a".into(), Json::Number(1))])]),
            ),
            ("a".into(), Json::Null),
        ]);

        assert_eq!(canonicalize(&value), r#"{"a":null,"z":[true,{"a":1}]}"#);
    }

    #[test]
    fn sorts_keys_by_utf16_code_units() {
        let value = Json::Object(vec![
            ("b".into(), Json::Null),
            ("a".into(), Json::Null),
        ]);

        assert_eq!(canonicalize(&value), r#"{"a":null,"b":null}"#);
    }

    #[test]
    fn escapes_quotes_backslashes_and_controls() {
        let value = Json::String("\"\\\u{08}\u{09}\u{0a}\u{0c}\u{0d}\u{1f}".into());

        assert_eq!(canonicalize(&value), r#""\"\\\b\t\n\f\r\u001f""#);
    }
}

